mapper.select:
SELECT l.id, COALESCE(l.customer_id, o.customer_id) AS customer_id, l.contact_id, l.lead_name, l.source, l.status, l.phone, l.email, l.company, l.description, l.owner_id, l.converted_time, l.converted_opp_id, l.create_time, l.update_time, u.user_name as owner_name, COALESCE(c.customer_name, oc.customer_name) AS customer_name, cc.contact_name, o.opp_name as converted_opp_name FROM crm_lead l LEFT JOIN sys_user u ON l.owner_id = u.id LEFT JOIN crm_opportunity o ON l.converted_opp_id = o.id LEFT JOIN crm_customer c ON l.customer_id = c.id LEFT JOIN crm_customer oc ON o.customer_id = oc.id LEFT JOIN crm_customer_contact cc ON l.contact_id = cc.id WHERE 1=1
AND l.lead_name LIKE CONCAT('%', #{query.leadName}, '%')
AND l.source = #{query.source}
AND l.status = #{query.status}
AND l.owner_id = #{query.ownerId}
AND l.company LIKE CONCAT('%', #{query.company}, '%')
AND l.phone LIKE CONCAT('%', #{query.phone}, '%')
ORDER BY l.create_time DESC
